        &mut env,
        "MANPATH",
        pkg_paths(pkgx_root, packages, "share/man"),
    );
    prepend_env_paths(
        &mut env,
        "PKG_CONFIG_PATH",
        pkg_paths(pkgx_root, packages, "lib/pkgconfig"),
    );
    prepend_env_paths(
        &mut env,
        "LIBRARY_PATH",
        pkg_paths(pkgx_root, packages, "lib"),
    );
    prepend_env_paths(
        &mut env,
        "LD_LIBRARY_PATH",
