        .iter()
        .map(|p| package_prefix(pkgx_root, &p.name, &p.version).join("ssl/cert.pem"))
        .find(|p| p.exists())
    {
        env.entry("SSL_CERT_FILE".into())
            .or_insert_with(|| ca_certs.to_string_lossy().to_string());
    }

