/// A minimum version: dot-separated components starting with a digit.
fn valid_min_version(min: &str) -> bool {
    min.as_bytes().first().is_some_and(u8::is_ascii_digit)
        && min
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b'+'))
}

