            checksum: statement
                .digest_of(&artifact.name)
                .map(|digest| format!("sha256:{digest}")),
            size: Some(artifact.size),
            url: Some(url),
            signer: Some(format!(
                "{scheme}:{}",
                packslip_pins::signer_of(&scheme, &verified.key_id)
            )),
            attested_by: (verified.attested_by == packslip::Attestor::Repackager)
