    resources.sort_by_key(|r| match r.source() {
        Some(ResourceSource::Archive) => 0,
        Some(ResourceSource::Asset) => 1,
        Some(ResourceSource::Repo) => 2,
        Some(ResourceSource::Exec) => 3,
        None => 4,
    });
