        Some(ResourceSource::Asset) => 1,
        Some(ResourceSource::Repo) => 2,
        Some(ResourceSource::Exec) => 3,
        None => 4,
    });
    for (index, resource) in resources.iter().copied().enumerate() {
        // Sources are alternatives, not a set to collect: once a higher
        // source has the skill on disk, the ones below it are not fetched
        // and, in particular, a shipped skill never runs the tool.
        if resource.kind == "skill"
            && resources[..index].iter().any(|higher| {
                higher.kind == "skill"
                    && skill_name(higher) == skill_name(resource)
                    && resource_dir(&tv.install_path(), higher).is_some()
            })
        {
            continue;
        }
        // An entry scoped to another platform is not for this install.
        if let Some(artifact) = artifact
            && !resource_fits(resource, artifact)
        {
            continue;
        }
        if resource.kind == "skill" && !fetch_skills {
            debug!(
                "{}: skills are not fetched (skills.fetch is off)",
                tv.style()
            );
            continue;
        }
        match resource.source() {
            Some(ResourceSource::Asset) => {
                let Some(name) = asset_name(resource) else {
                    warn!(
                        "{}: the packslip names an asset {:?}, which is not a plain file name",
                        tv.style(),
                        resource.asset.as_deref().unwrap_or_default()
                    );
                    continue;
                };
                let dest = base.join("assets").join(name);
                if !dest.exists() {
                    let Some(url) = &resource.url else {
                        warn!("{}: asset {name} has no download URL", tv.style());
                        continue;
                    };
                    pr.set_message(format!("download {name}"));
                    file::create_dir_all(dest.parent().unwrap_or(&base))?;
                    // The tool is installed by now and the asset is an extra:
                    // one that cannot be fetched is reported, not fatal. One
                    // that arrives with the wrong digest is another matter.
                    if let Err(err) = HTTP
                        .download_file_with_headers(url, &dest, &headers_for(url)?, Some(pr))
                        .await
                    {
                        let _ = file::remove_all(&dest);
                        warn!("{}: could not fetch {name}: {err}", tv.style());
                        continue;
                    }
                    let (actual, _) = packslip::digest_file(&dest)?;
                    let expected = statement.digest_of(name);
                    if expected != Some(actual.as_str()) {
                        let _ = file::remove_all(&dest);
                        bail!(
                            "{name}: sha256 is {actual}, the packslip says {}",
                            expected.unwrap_or("it is not a subject")
                        );
                    }
                }
                // The archive and the unpacked skill are separate: an archive
                // left by an earlier attempt still needs unpacking.
                if resource.kind == "skill"
                    && let Some(skill) = skill_name(resource)
                {
                    let dir = base.join("skills").join(skill);
                    // Like the other skill sources: a skill that cannot be
                    // unpacked is reported, and the tool still installs. The
                    // digest check above stays fatal.
                    if !dir.join("SKILL.md").is_file()
                        && let Err(err) = unpack_skill(&dest, &dir, pr)
                    {
                        warn!("{}: could not unpack skill {skill}: {err}", tv.style());
                    }
                }
            }
            Some(ResourceSource::Repo) if resource.kind == "skill" => {
                let commit = statement
                    .predicate
                    .source
                    .as_ref()
                    .and_then(|s| s.commit.as_deref());
                let (Some(rel), Some(commit)) = (repo_path(resource), commit) else {
                    warn!(
                        "{}: skill {:?} in the source repository is not pinned by a commit, or its path is not safe to fetch",
                        tv.style(),
                        resource.repo.as_deref().unwrap_or_default()
                    );
                    continue;
                };
                let dest = base.join("repo").join(rel);
                // A finished skill holds SKILL.md; a bare directory may be
                // no more than a parent that fetching a file created.
                if dest.join("SKILL.md").is_file() {
                    continue;
                }
                let Some(repo) = github_repo(statement) else {
                    warn!(
                        "{}: skill {rel} lives in the source repository, which mise can only read on github.com",
                        tv.style()
                    );
                    continue;
                };
                // Built beside its final place and moved there whole, so a
                // half-fetched skill never passes for a finished one.
                let fetched = match staging_dir(&dest) {
                    Ok(staging) => {
                        let built = fetch_repo_dir(&repo, commit, rel, &staging, pr).await;
                        into_place(&staging, &dest, built)
                    }
                    Err(err) => Err(err),
                };
                if let Err(err) = fetched {
                    warn!(
                        "{}: could not fetch skill {rel} from the source repository: {err}",
                        tv.style()
                    );
                }
            }
            Some(ResourceSource::Exec) if resource.kind == "skill" => {
                let Some(skill) = skill_name(resource) else {
                    continue;
                };
                let dir = base.join("skills").join(skill);
                if dir.join("SKILL.md").is_file() {
                    continue;
                }
                if !Settings::get().packslip.exec {
                    debug!(
                        "{}: skill {skill} is generated by running the tool; packslip.exec is off",
                        tv.style()
                    );
                    continue;
                }
                let Some((program, args)) = resource.exec.split_first() else {
                    continue;
                };
                let Some(path) = installed_bin(&tv.install_path(), program) else {
                    warn!(
                        "{}: skill {skill} is generated by {program}, which the install does not hold",
                        tv.style()
                    );
                    continue;
                };
                pr.set_message(format!("generate skill {skill}"));
                let generated = match run_resource_command(
                    &path,
                    args,
                    &resource.env,
                    &tv.install_path(),
                    std::time::Duration::from_secs(5),
                )
                .await
                {
                    // Written beside its place and moved whole, like a fetched skill.
                    Ok(text) => staging_dir(&dir).and_then(|staging| {
                        let written = file::write(staging.join("SKILL.md"), text);
                        into_place(&staging, &dir, written)
                    }),
                    Err(err) => Err(err),
                };
                if let Err(err) = generated {
                    warn!("{}: could not generate skill {skill}: {err}", tv.style());
                }
            }
            Some(ResourceSource::Repo) => {
                let Some(rel) = repo_path(resource) else {
                    warn!(
                        "{}: the packslip names a repository path {:?}, which is not safe to fetch",
                        tv.style(),
                        resource.repo.as_deref().unwrap_or_default()
                    );
                    continue;
                };
                let dest = base.join("repo").join(rel);
                if dest.exists() {
                    continue;
                }
                let Some((url, headers)) = repo_file_request(statement, rel) else {
                    warn!(
                        "{}: {rel} comes from the source repository, which mise cannot read files from",
                        tv.style()
                    );
                    continue;
                };
                pr.set_message(format!("download {rel}"));
                file::create_dir_all(dest.parent().unwrap_or(&base))?;
                if let Err(err) = HTTP
                    .download_file_with_headers(&url, &dest, &headers, Some(pr))
                    .await
                {
                    warn!(
                        "{}: could not fetch {rel} from the source repository: {err}",
                        tv.style()
                    );
                }
            }
            _ => {}
        }
    }
    Ok(())
}

/// An executable of the install, by the name the packslip gave it.
fn installed_bin(install_path: &Path, program: &str) -> Option<PathBuf> {
    if !is_safe_relative(program) {
        return None;
    }
    let linked = install_path.join(MISE_BINS_DIR).join(program);
    if linked.exists() {
        return Some(linked);
    }
    locate_in_install(install_path, program)
}

/// Unpack a skill shipped as its own archive, dropping a lone top-level
/// directory the way artifacts are unpacked.
fn unpack_skill(archive: &Path, dir: &Path, pr: &dyn SingleReport) -> Result<()> {
    let name = archive.file_name().unwrap_or_default().to_string_lossy();
    let format = file::ExtractionFormat::from_file_name(&name);
    if !format.is_archive() {
        bail!("skill asset {name} is not an archive mise can unpack");
    }
    let strip_components = usize::from(file::should_strip_components(archive, format)?);
    let staging = staging_dir(dir)?;
    let unpacked = file::extract_archive(
        archive,
        &staging,
        format,
        &file::ExtractOptions {
            strip_components,
            pr: Some(pr),
            ..Default::default()
        },
    );
    into_place(&staging, dir, unpacked)
}

/// A fresh sibling directory to build a skill in, so `dir` only ever
/// exists once it is complete and an interrupted attempt cannot pass for
/// a finished one on the next install.
use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;
use std::sync::Arc;
use std::time::SystemTime;

use eyre::Result;

use crate::config::env_directive::{EnvResolveOptions, EnvResults, ToolsFilter};
use crate::config::{Config, Settings};
use crate::env::{PATH_KEY, WARN_ON_MISSING_REQUIRED_ENV};
use crate::env_diff::EnvMap;
use crate::install_context::InstallDependencyContext;
use crate::path_env::PathEnv;
use crate::toolset::Toolset;
use crate::toolset::env_cache::{CachedEnv, compute_settings_hash, get_file_mtime};
use crate::toolset::tool_request::ToolRequest;
use crate::{env, file, github, parallel, uv};

/// PATH with mise-managed install dirs filtered out. mise re-adds the current
/// toolset's bin dirs below, so a stale `installs/<tool>/<ver>/bin` left on PATH
/// (e.g. carried in from a frozen env snapshot) does not outrank the version that
/// `mise x`/`run`/`env` selects for the whole process tree. Mirrors the hook-env
/// reactivation filter from #10162. (#10345)
fn pristine_path_without_install_dirs() -> Vec<PathBuf> {
    let install_dirs = crate::path_env::mise_install_dirs();
    env::PATH
        .iter()
        .filter(|p| !crate::path_env::is_mise_install_path(p.as_path(), &install_dirs))
        .cloned()
        .collect()
}

impl Toolset {
    /// PATH for an environment mise hands to a child process or prints (`mise x`,
    /// `mise run`, `mise env`): the pristine PATH with the given mise-managed paths
    /// ahead of it.
    ///
    /// The pristine PATH never contains a shim farm that PATH activation added on its
    /// own, and a shell without activation may not have one at all. A `lazy = true`
    /// tool relies on its bootstrap shim being found, so when the toolset declares one
    /// the farms follow the tool paths, mirroring the fallback boundary hook-env retains
    /// in the interactive shell. Installed tools still resolve to their real bin
    /// directories first. A farm already on the pristine PATH keeps its place: `PathEnv`
    /// already puts tool paths ahead of it, and a shared directory such as
    /// `~/.local/bin` must not be reordered.
    fn child_path(&self, paths: impl IntoIterator<Item = PathBuf>) -> String {
        let mut pristine = pristine_path_without_install_dirs();
        let mut shim_farms = Vec::new();
        let mut shim_boundary = None;
        if self.has_lazy_declarations() {
            shim_farms = crate::shims::shim_farm_dirs();
            for (index, path) in pristine.iter().enumerate() {
                if shim_farms.iter().any(|farm| {
                    file::paths_eq(
                        &file::canonicalize_or_self(path),
                        &file::canonicalize_or_self(farm),
                    )
                }) {
                    shim_boundary.get_or_insert(index);
                }
            }
            if let Some(boundary) = shim_boundary {
                pristine.retain(|path| {
                    !shim_farms.iter().any(|farm| {
                        file::paths_eq(
                            &file::canonicalize_or_self(path),
                            &file::canonicalize_or_self(farm),
                        )
                    })
                });
                pristine.splice(boundary..boundary, shim_farms.iter().cloned());
            }
        }
        let mut path_env = PathEnv::from_iter(pristine.iter().cloned());
        for p in paths {
            path_env.add(p);
        }
        if shim_boundary.is_none() {
            for dir in shim_farms {
                path_env.add(dir);
            }
        }
        path_env.to_string()
    }

    pub(crate) async fn full_env(&self, config: &Arc<Config>) -> Result<EnvMap> {
        Ok(self.full_env_with_removals(config).await?.0)
    }

    pub(crate) async fn full_env_with_removals(
        &self,
        config: &Arc<Config>,
    ) -> Result<(EnvMap, BTreeSet<String>)> {
        let (mise_env, env_remove) = self.env_with_path_and_removals(config).await?;
        let mut env = env::PRISTINE_ENV.clone().into_iter().collect::<EnvMap>();
        for key in &env_remove {
            env.remove(key);
        }
        env.extend(mise_env);
        Ok((env, env_remove))
    }

    /// Like full_env but skips `tools=true` env directives (load_post_env).
    /// Used for preinstall hooks where tool-dependent env vars aren't available yet,
    /// and for dependency_env where resolving tools=true modules on a partial toolset
    /// would trigger spurious errors from modules expecting the full PATH.
    pub(crate) async fn full_env_without_tools(&self, config: &Arc<Config>) -> Result<EnvMap> {
        let mut env = env::PRISTINE_ENV.clone().into_iter().collect::<EnvMap>();
        for key in &config.env_results().await?.env_remove {
            env.remove(key);
        }
        env.extend(self.env_with_path_without_tools(config).await?);
        Ok(env)
    }
}

impl InstallDependencyContext {
    /// Build an install-hook base environment from this context's resolved
    /// dependency toolset and its already-validated paths. `tools = true`
    /// directives remain excluded because a partial install context cannot
    /// evaluate arbitrary modules.
    pub(crate) async fn base_env_for_install(&self, config: &Arc<Config>) -> Result<EnvMap> {
        let mut full_env = env::PRISTINE_ENV.clone().into_iter().collect::<EnvMap>();
        for key in &config.env_results().await?.env_remove {
            full_env.remove(key);
        }
        let (mut env, add_paths) = self.toolset.env(config).await?;
        let mut path_env = PathEnv::new();
        for path in &self.paths {
            path_env.add(path.clone());
        }
        for path in config.path_dirs().await?.clone() {
            path_env.add(path);
        }
        for path in add_paths {
            path_env.add(path);
        }
        for path in pristine_path_without_install_dirs() {
            path_env.add(path);
        }
        env.insert(PATH_KEY.to_string(), path_env.to_string());
        full_env.extend(env);
        Ok(full_env)
    }
}

impl Toolset {
    /// Like env_with_path but skips `tools=true` env directives.
    /// Used during tool installation where tool-dependent env vars
    /// may reference tools that aren't installed yet, and in
    /// dependency_env to avoid triggering module hooks on a partial PATH.
    pub(crate) async fn env_with_path_without_tools(&self, config: &Arc<Config>) -> Result<EnvMap> {
        let (mut env, add_paths) = self.env(config).await?;
        let mut path_env = PathEnv::from_iter(pristine_path_without_install_dirs());
        for p in config.path_dirs().await?.clone() {
            path_env.add(p);
