        let s = basic();
        assert_eq!(
            repo_file_request(&s, "docs/a?b#c.md").unwrap().0,
            format!(
                "https://api.github.com/repos/o/r/contents/docs/a%3Fb%23c.md?ref={}",
                "c".repeat(40)
