    pub(super) async fn load_post_env(
        &self,
        config: &Arc<Config>,
        ctx: tera::Context,
        env: &EnvMap,
        tools_filter: ToolsFilter,
    ) -> Result<EnvResults> {
        if Settings::no_env() || Settings::get().no_env.unwrap_or(false) {
            return Ok(EnvResults::default());
        }
        let entries = config
            .config_files
            .iter()
            .rev()
            .map(|(source, cf)| {
                cf.env_entries()
                    .map(|ee| ee.into_iter().map(|e| (e, source.clone())))
            })
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .flatten()
            .collect();
        // trace!("load_env: entries: {:#?}", entries);
        let env_results = EnvResults::resolve_with_toolset(
            config,
            ctx,
            env,
            entries,
            EnvResolveOptions {
                vars: false,
                tools: tools_filter,
                warn_on_missing_required: *WARN_ON_MISSING_REQUIRED_ENV,
            },
            // `_.python.venv` needs the *active* python, which is only knowable here: a
            // `--tool python@3.12` override lives in this toolset and never reaches `Config`.
            Some(self),
        )
        .await?;
        if log::log_enabled!(log::Level::Trace) {
            trace!("{env_results:#?}");
        } else if !env_results.is_empty() {
            debug!("{env_results:?}");
        }
        Ok(env_results)
        return Ok(());
    }
    file::write_atomic(&path, serde_json::to_string_pretty(state)?)
}

/// The skills a statement declares that are present in the install.
pub(crate) fn skills_of(
    statement: &Statement,
    install_path: &Path,
    tool: &str,
    version: &str,
    artifact: Option<&Artifact>,
) -> Vec<Skill> {
    // A vendor may offer one skill from several sources, as completions
    // are offered; the most verifiable one that is on disk is the skill.
    let rank = |r: &Resource| match r.source() {
        Some(ResourceSource::Archive) => 0,
        Some(ResourceSource::Asset) => 1,
        Some(ResourceSource::Repo) => 2,
        Some(ResourceSource::Exec) => 3,
        None => 4,
    };
    // Each name is its own skill, so platform scope is resolved per name:
    // a skill for one platform never hides the skills for every platform.
    let skills: Vec<&Resource> = statement
        .predicate
        .resources
        .iter()
        .filter(|r| r.kind == "skill")
        .collect();
    let mut names: Vec<&str> = Vec::new();
    for name in skills.iter().filter_map(|r| skill_name(r)) {
        if !names.contains(&name) {
            names.push(name);
        }
    }
    let mut chosen: Vec<(usize, Skill)> = Vec::new();
    for name in names {
        let mut group = applicable(
            skills
                .iter()
                .copied()
                .filter(|r| skill_name(r) == Some(name)),
            artifact,
        );
        group.sort_by_key(|r| rank(r));
        if let Some((r, path)) = group
            .into_iter()
            .find_map(|r| resource_dir(install_path, r).map(|p| (r, p)))
        {
            chosen.push((
                rank(r),
                Skill {
                    name: name.to_string(),
                    tool: tool.to_string(),
                    version: version.to_string(),
                    path,
                },
            ));
        }
    }
    chosen.sort_by_key(|(rank, _)| *rank);
    chosen.into_iter().map(|(_, skill)| skill).collect()
}

